/**
 * The transport strip's tables (#708, epic #703 decision 1): the tempo and
 * bars boxes' ranges and drag feel (windsor#12), tap tempo, the swing box and
 * its grid picker (windsor#29), the meter picker (windsor#431), the key and
 * scale options, and the position readout's sixteenth. Every range is the engine's or
 * the new song's; nothing is restated.
 */
import {
  BARS_MAX,
  BARS_MIN,
  BPM_MAX,
  BPM_MIN,
  CHORD_NOTE_NAMES,
  DIVISORS,
  METERS,
  PITCH_CLASS_MAX,
  STRAIGHT_SWING,
  SWING_AMOUNT_MAX,
  SWING_AMOUNT_MIN,
  type SwingGrid,
} from '@windsor/engine';
import { fmt0, fmt2 } from './consoleFormat';
import type { KnobSpec } from './knob';
import type { SelectGroup, SelectOption } from './dom';
import { SCALE_DISPLAY_NAMES, SCALE_GROUPS } from './scaleNameTables';
import { DRAG_RANGE_FINE_PX, DRAG_RANGE_PX } from './knobConstants';
import { NEW_SONG_BARS, NEW_SONG_BPM } from './songConstants';

export type KnobRange = Pick<KnobSpec, 'label' | 'min' | 'max' | 'def' | 'step' | 'fmt'>;

/**
 * The tempo box: the engine's range, and what a new song starts at (#617).
 * Shown and stepped to two decimals, as Ableton Live's tempo field is
 * (windsor#12), so a typed 133.5 or a tapped tempo lands as it is, and a drag
 * sweeps smoothly.
 */
export const BPM_KNOB: KnobRange = {
  label: 'BPM',
  min: BPM_MIN,
  max: BPM_MAX,
  def: NEW_SONG_BPM,
  step: 0.01,
  fmt: fmt2,
};

/** The song's length in bars (#705, decision 5): the engine's range, and what a new song starts at. */
export const BARS_KNOB: KnobRange = {
  label: 'Bars',
  min: BARS_MIN,
  max: BARS_MAX,
  def: NEW_SONG_BARS,
  step: 1,
  fmt: fmt0,
};

/**
 * The swing box (windsor#29 decision 1): the engine's amount range, in whole
 * percent, starting straight. 50 reads as straight, 66 near a triplet, 75 hard.
 */
export const SWING_KNOB: KnobRange = {
  label: 'Swing',
  min: SWING_AMOUNT_MIN,
  max: SWING_AMOUNT_MAX,
  def: STRAIGHT_SWING.amount,
  step: 1,
  fmt: fmt0,
};
export const SWING_UNIT = '%';

/**
 * The swing grid picker (windsor#29 decision 2), 16ths first: the engine's
 * grids, each named as the note it swings.
 */
export const SWING_GRID_LABEL = 'Swing grid';
const SWING_GRID_ORDER: readonly SwingGrid[] = [16, 8];
const SWING_GRID_NAMES: Readonly<Record<SwingGrid, string>> = { 16: '1/16', 8: '1/8' };
export const SWING_GRID_OPTIONS: readonly { value: string; label: string }[] = SWING_GRID_ORDER.map(
  (grid) => ({ value: String(grid), label: SWING_GRID_NAMES[grid] }),
);

/**
 * How a vertical drag on a number box moves it (windsor#12 decision 2): the
 * knob's sensitivity — `DRAG_RANGE_PX` of travel sweeps the whole range,
 * `DRAG_RANGE_FINE_PX` under shift — and the few pixels a press may wander
 * before it counts as a drag rather than a click to type.
 */
export interface DragFeel {
  readonly rangePx: number;
  readonly fineRangePx: number;
}
export const NUMBER_DRAG: DragFeel = { rangePx: DRAG_RANGE_PX, fineRangePx: DRAG_RANGE_FINE_PX };
export const NUMBER_DRAG_THRESHOLD_PX = 3;

/** A drag on Bars moves it in whole phrases of this many bars, snapping to multiples of it. */
export const BARS_DRAG_STEP = 4;

/**
 * Tap tempo (windsor#12 decision 4): the average of the last `intervals` tap
 * intervals, and a gap of `resetMs` or longer starts a new average.
 */
export interface TapTempo {
  readonly intervals: number;
  readonly resetMs: number;
}
export const TAP_TEMPO: TapTempo = { intervals: 4, resetMs: 2000 };
export const MS_PER_MINUTE = 60_000;

/**
 * The meter picker (windsor#431 decision 1): the engine's meters in its
 * order, each named by its bare time signature (`7/8`, not `7/8 (2+2+3)`).
 */
export const METER_LABEL = 'Meter';
export const METER_OPTIONS: readonly { value: string; label: string }[] = METERS.map((meter) => ({
  value: meter,
  label: meter,
}));

/** The twelve pitch classes, spelt as `chordNames.ts` prints them (sharps). */
export const KEY_OPTIONS: readonly { value: string; label: string }[] = CHORD_NOTE_NAMES.slice(
  0,
  PITCH_CLASS_MAX + 1,
).map((name, pc) => ({ value: String(pc), label: name }));

/** A custom offset list shows as this, after the groups. */
export const CUSTOM_SCALE = 'custom';
/** The named scales under their groups (windsor#721 decision 3), by display name. */
export const SCALE_OPTION_GROUPS: readonly SelectGroup[] = SCALE_GROUPS.map((group) => ({
  group: group.label,
  options: group.scales.map((name) => ({ value: name, label: SCALE_DISPLAY_NAMES[name] })),
}));
/** Every named scale's option, in the picker's order. */
export const SCALE_OPTIONS: readonly SelectOption[] = SCALE_OPTION_GROUPS.flatMap((g) => g.options);

/**
 * The position readout's third field (windsor#431 decision 3): 16ths inside
 * the counted beat in every meter, 1–6 in a dotted-quarter beat.
 */
export const POSITION_SIXTEENTH = DIVISORS.sixteenth;
